'use strict'

/*
 * App user accounts — generated by vfs_scaffold_auth (see README.md in this folder).
 * These are the app's OWN users, separate from whoever hosts or previews the app.
 *
 *   const { mountAuth, requireUser, requireRole } = require('./auth')
 *   mountAuth(app)                                              // serves /auth/* (signup, login, logout, me, users...)
 *   app.get('/api/orders', requireUser, handler)                // req.user = { id, email, name, roles }
 *   app.delete('/api/orders/:id', requireRole('admin'), handler)
 *
 * Do not hand-write login, password or session code next to this module: extend it here instead.
 */

const config = require('./config')
const store = require('./store')
const { createAuthRouter, requireUser, requireRole, currentUser } = require('./routes')

function mountAuth(app, { path = config.routePrefix } = {}) {
  // Behind the preview proxies every request comes from a private address: trust them so req.ip (used by the login
  // rate limit) is the visitor's, unless the app already decided how to trust proxies.
  if (!app.get('trust proxy')) app.set('trust proxy', 'loopback, linklocal, uniquelocal')
  // Create the tables (idempotent) as soon as the server starts; requests wait for it.
  store.ready().catch((error) => console.error('[auth] database setup failed:', error.message))
  app.use(path, createAuthRouter())
  return app
}

module.exports = { mountAuth, requireUser, requireRole, currentUser, config }
